type User struct {
    Name string
    Age int
}

func (user User) Label() string {
    return user.Name
}

func (user *User) Birthday() {
    user.Age++
}

type Labeler interface {
    Label() string
}

func divide(a float64, b float64) (float64, error) {
    if b == 0 {
        fail errors.New("division by zero")
    }
    return a / b, nil
}

func counter() func() int {
    value := 0
    return func() int {
        value++
        return value
    }
}

